package net.officefloor.hq.app.claim;

/** Where a claim is in its life: DRAFT, then OPEN, then SETTLED; a DRAFT, OPEN or PENDING claim can be VOID. A clerk
 *  settling an OPEN claim above the clerk limit makes it PENDING, which a steward approves (SETTLED) or rejects
 *  (OPEN again). */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID;

    /** Whether a claim in this status may move to {@code next} by a status change; approving or rejecting a
     *  PENDING claim is not a status change. */
    public boolean canBecome(ClaimStatus next) {
        return switch (next) {
            case OPEN -> this == DRAFT;
            case SETTLED -> this == OPEN;
            case VOID -> this == DRAFT || this == OPEN || this == PENDING;
            case DRAFT, PENDING -> false;
        };
    }

    /** Whether a claim in this status counts toward what is claimed and due: OPEN, PENDING and SETTLED ones do. */
    public boolean counts() {
        return this == OPEN || this == PENDING || this == SETTLED;
    }

    /** Whether a claim in this status is still open: OPEN or PENDING, so it goes overdue and gains the late charge. */
    public boolean isOpen() {
        return this == OPEN || this == PENDING;
    }
}
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.audit = audit;
    }

    /** The sheet's figures as the store holds them now. */
    public Figures of(String sheetId) {
        Sheet sheet = sheets.findById(sheetId).orElse(null);
        LocalDate today = sheet == null ? null : sheet.getToday();
        List<Rate> sheetRates = rates.findBySheetId(sheetId);
        List<Claim> sheetClaims = claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
        Map<Long, PersonFigures> byPerson = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
            List<Claim> counting = sheetClaims.stream()
                    .filter(c -> c.getPersonId().equals(person.getId()) && person.counts(c.getStatus()))
                    .toList();
            BigDecimal claimed = counting.stream().map(Claim::getAmount)
                    .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
            claimedTotal = claimedTotal.add(claimed);
            // As on screen: with no rate in force today for their grade on the sheet's today, nor for the grade
            // any of their claims is at, and no fixed figure, the person has no due-total.
            boolean anyFixed = counting.stream().anyMatch(c -> c.getSettledDue() != null || c.getBoundDue() != null);
            boolean anyRate = today != null && Stream.concat(Stream.of(person.gradeOn(today)),
                            counting.stream().map(c -> person.gradeOn(c.getDate())))
                    .anyMatch(grade -> Rate.inForceOn(ratesOf(sheetRates, grade), today).isPresent());
            String due = NOT_AVAILABLE;
            if (anyFixed || anyRate) {
                BigDecimal total = counting.stream().map(c -> dueOf(c, ratesOf(sheetRates, person.gradeOn(c.getDate())), sheet, sheetClaims))
                        .filter(Objects::nonNull)
                        .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
                dueTotal = dueTotal.add(total);
                due = total.toPlainString();
            }
            byPerson.put(person.getId(), new PersonFigures(person.getName(), claimed.toPlainString(), due));
        }
        return new Figures(byPerson, claimedTotal.toPlainString(), dueTotal.toPlainString());
    }

    /** The due-total of the claims that count (a held person's OPEN ones do not) dated from {@code from} to {@code to} inclusive, as the
     *  screen shows a period's: each claim's due, none counting as 0. */
    public BigDecimal dueTotalBetween(String sheetId, LocalDate from, LocalDate to) {
        List<Rate> sheetRates = rates.findBySheetId(sheetId);
        Sheet sheet = sheets.findById(sheetId).orElse(null);
        Map<Long, Person> personOf = new LinkedHashMap<>();
        people.findBySheetIdOrderByIdAsc(sheetId).forEach(p -> personOf.put(p.getId(), p));
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        List<Claim> sheetClaims = claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
        for (Claim claim : sheetClaims) {
            Person person = personOf.get(claim.getPersonId());
            if (person == null || !person.counts(claim.getStatus()) || claim.getDate().isBefore(from) || claim.getDate().isAfter(to)) {
                continue;
            }
            BigDecimal due = dueOf(claim, ratesOf(sheetRates, person.gradeOn(claim.getDate())), sheet, sheetClaims);
            if (due != null) {
                total = total.add(due);
            }
        }
        return total;
    }

    /**
     * Record, once the change commits, how the sheet's figures moved since {@code before}: a ROLLUP line
     * for each person whose figures changed (one who did not exist before counting as changed), then a
     * TOTALS line if the sheet's totals changed. Nothing is recorded when no figure moved.
     */
    public void recordChanges(String sheetId, String user, Figures before) {
        Figures after = of(sheetId);
        after.people().forEach((id, figures) -> {
            PersonFigures was = before.people().get(id);
            if (was == null || !was.claimed().equals(figures.claimed()) || !was.dueTotal().equals(figures.dueTotal())) {
                audit.recordOnCommit("ROLLUP sheet=" + sheetId + " by=" + user + " person=" + figures.name()
                        + " claimed=" + figures.claimed() + " due-total=" + figures.dueTotal());
            }
        });
        if (!before.claimedTotal().equals(after.claimedTotal()) || !before.dueTotal().equals(after.dueTotal())) {
            audit.recordOnCommit("TOTALS sheet=" + sheetId + " by=" + user + " claimed-total=" + after.claimedTotal()
                    + " due-total=" + after.dueTotal());
        }
    }

    /**
     * Take a statement of a person: record their due-total now (with the late charges their overdue claims have gained), bind each of their claims that counts
     * to the figure it has now (its settled figure, else the figure it is bound to, else its amount at
     * its grade's rate in force on its date) and leave the rest unbound. A late charge is never bound: it keeps
     * following the sheet's today. The sheet is locked first, so
     * a statement is not taken while a claim on it changes.
     */
    @Transactional
    public Taken take(String sheetId, String user, long personId) {
        sheets.load(sheetId, user);
        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
        LocalDate today = sheet.getToday();
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
        Rollup.Figures before = rollup.of(sheetId);
        List<Rate> sheetRates = rates.findBySheetId(sheetId);
        Set<String> grades = new HashSet<>(Set.of(person.gradeOn(today)));
        List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByListedDescIdDesc(sheetId, personId);

        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean anyFixed = false;
        int counted = 0;
        for (Claim claim : theirs) {
            if (!person.counts(claim.getStatus())) {
                claim.unbind();
                continue;
            }
            BigDecimal fixed = claim.getSettledDue() != null ? claim.getSettledDue() : claim.getBoundDue();
            BigDecimal figure = fixed != null ? fixed
                    : Rate.inForceOn(ratesOf(sheetRates, person.gradeOn(claim.getDate())), claim.getDate())
                            .map(rate -> ClaimService.liveFigure(claim, rate.getRate(), sheet.getFloor(),
                                    sheet.roundingFor(ClaimService.roundingDate(claim, theirs))))
                            .orElse(null);
            anyFixed |= fixed != null;
            grades.add(person.gradeOn(claim.getDate()));
            total = figure == null ? total : total.add(figure).add(ClaimService.lateCharge(claim, figure, sheet));
            claim.bind(figure);
            counted++;
        }
        // As on screen: with no rate in force today for their grade on the sheet's today, nor for the grade any
        // of their claims that count is at, and no fixed figure, the person has no due-total.
        boolean anyRate = grades.stream().anyMatch(g -> Rate.inForceOn(ratesOf(sheetRates, g), today).isPresent());
        String dueTotal = !anyRate && !anyFixed ? "n/a" : total.toPlainString();
        claims.saveAllAndFlush(theirs);
        statements.saveAndFlush(new Statement(sheetId, personId, dueTotal, today));
        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " due-total=" + dueTotal + " claims=" + counted);
        rollup.recordChanges(sheetId, user, before);
        List<Statement> taken = statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId);
   *  decimals; null when not bound, while PENDING, or if it had no figure then (it then follows the rate). */
  statedDue: string | null;
  /** The number of the SETTLED claim of the same person a correction (a negative amount) corrects; null on
   *  any other claim. */
  corrects: string | null;
  /** The day the claim is due by (yyyy-mm-dd): fixed when it was added, from its date and the terms of its
   *  person's grade in force then. */
  dueBy: string;
  /** The claim's status log, oldest first: a line for each status it has had, the DRAFT it was added as first. */
  log: ClaimLogLine[];
}

/** A line of a claim's status log: the status it took, the signed-in name of who moved it there, the sheet's
 *  today (yyyy-mm-dd) then, and the due it had at that moment with exactly two decimals (null when it had none). */
export interface ClaimLogLine {
  status: ClaimStatus;
  by: string;
  on: string;
  due: string | null;
}

/** Only OPEN, PENDING and SETTLED claims count toward what is claimed and due. */
export function counts(c: ClaimView): boolean {
  return c.status === 'OPEN' || c.status === 'PENDING' || c.status === 'SETTLED';
}

/** Whether the claim counts in the live totals for a person held or not: while held, only SETTLED ones do. */
export function countsWhile(held: boolean): (c: ClaimView) => boolean {
  return held ? (c) => c.status === 'SETTLED' : counts;
}

/** The date (yyyy-mm-dd) that decides how a claim's live figures round: its own, or for a correction the date
 *  of the claim of the same person it corrects, found among that person's claims. */
export function roundingDate(
  c: Pick<ClaimView, 'date' | 'corrects'>,
  theirs: readonly Pick<ClaimView, 'date' | 'number'>[],
): string {
  if (c.corrects === null) return c.date;
  return theirs.find((o) => o.number === c.corrects)?.date ?? c.date;
}

/** Whether a claim is overdue on the sheet's today: OPEN or PENDING and due by a day before it. */
export function isOverdue(c: Pick<ClaimView, 'dueBy' | 'status'>, today: string): boolean {
  return (c.status === 'OPEN' || c.status === 'PENDING') && c.dueBy < today;
}

/** A claim as the form submits it: a blank date takes the sheet's today. A negative amount is a correction,
 *  which names in `corrects` the number of the claim it corrects. */
export interface ClaimForm {
  amount: string;
  date: string | null;
import { HttpClient } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { Observable } from 'rxjs';

export type Grade = 'A' | 'B' | 'C';
export const GRADES: readonly Grade[] = ['A', 'B', 'C'];

/** A grade recorded for a person, in force from its from-date (yyyy-mm-dd) until the next one's; the
 *  first grade a person was given has none: it applies from the beginning of time. */
export interface GradeFrom {
  grade: Grade;
  from: string | null;
}

export interface PersonView {
  id: number;
  name: string;
  /** The grade in force on the sheet's today when the person was read. */
  grade: Grade;
  /** Every grade recorded, in the order they take effect. */
  grades: GradeFrom[];
  /** Raised on every save; an edit names the version it was made from. */
  version: number;
  /** Retired as soon as a retirement date is set, whatever the date. */
  retired: boolean;
  /** The date the person is retired from (yyyy-mm-dd); null while not retired. */
  retiredFrom: string | null;
  /** On hold: their OPEN claims count in no live total; their SETTLED ones still do. */
  held: boolean;
}

export interface PersonForm {
  name: string;
  grade: Grade;
}

/** An edit of a person: the grade is recorded from `gradeFrom` (yyyy-mm-dd; null takes the sheet's today). */
export interface PersonEdit extends PersonForm {
  gradeFrom: string | null;
}

/** The person's grade in force on `date` (yyyy-mm-dd): the one with the latest from-date on or before it. */
export function gradeOn(p: Pick<PersonView, 'grade' | 'grades'>, date: string): Grade {
  let inForce: GradeFrom | undefined;
  for (const g of p.grades) {
    if ((g.from === null || g.from <= date) && (inForce === undefined || (inForce.from ?? '') <= (g.from ?? ''))) inForce = g;
  }
  return inForce?.grade ?? p.grade;
}

// The people kept on a sheet, listed in the order they were added.
@Injectable({ providedIn: 'root' })
export class People {
  private readonly http = inject(HttpClient);
  /** Whether retired people are listed: belongs to the screen, so loading a sheet leaves it as it is. */
  readonly showRetired = signal(false);

  list(sheetId: string): Observable<PersonView[]> {
    return this.http.get<PersonView[]>(this.base(sheetId));
  }

  add(sheetId: string, person: PersonForm): Observable<PersonView> {
    return this.http.post<PersonView>(this.base(sheetId), person);
  }

  /** Save an edit made from `version` of the person; refused (412) when someone has saved them since. */
  update(sheetId: string, id: number, version: number, person: PersonEdit): Observable<PersonView> {
    return this.http.put<PersonView>(`${this.base(sheetId)}/${id}`, { ...person, version });
  }

  /** Retire the person from `from` (yyyy-mm-dd); null takes the sheet's today. */
  retire(sheetId: string, id: number, from: string | null): Observable<PersonView> {
    return this.http.post<PersonView>(`${this.base(sheetId)}/${id}/retire`, { from });
  }

  /** Put the person on hold, or take them off hold when held. */
  toggleHold(sheetId: string, id: number): Observable<PersonView> {
    return this.http.post<PersonView>(`${this.base(sheetId)}/${id}/hold`, {});
  }

  private base(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/people`;
  }
}

