            claim.bind(figure);
            counted++;
        }
        // As on screen: with no rate in force today for their grade on the sheet's today, nor for the grade any
        // of their claims that count is at, and no fixed figure, the person has no due-total.
        boolean anyRate = grades.stream().anyMatch(g -> Rate.inForceOn(ratesOf(sheetRates, g), today).isPresent());
        String dueTotal = !anyRate && !anyFixed ? "n/a" : total.toPlainString();
        claims.saveAllAndFlush(theirs);
        statements.saveAndFlush(new Statement(sheetId, personId, dueTotal, today));
        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " due-total=" + dueTotal + " claims=" + counted);
        rollup.recordChanges(sheetId, user, before);
        List<Statement> taken = statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId);
   *  decimals; null when not bound, while PENDING, or if it had no figure then (it then follows the rate). */
  statedDue: string | null;
  /** The number of the SETTLED claim of the same person a correction (a negative amount) corrects; null on
   *  any other claim. */
  corrects: string | null;
  /** The day the claim is due by (yyyy-mm-dd): fixed when it was added, from its date and the terms of its
   *  person's grade in force then. */
  dueBy: string;
  /** The claim's status log, oldest first: a line for each status it has had, the DRAFT it was added as first. */
  log: ClaimLogLine[];
}

/** A line of a claim's status log: the status it took, the signed-in name of who moved it there, the sheet's
 *  today (yyyy-mm-dd) then, and the due it had at that moment with exactly two decimals (null when it had none). */
export interface ClaimLogLine {
  status: ClaimStatus;
  by: string;
  on: string;
  due: string | null;
}

/** Only OPEN, PENDING and SETTLED claims count toward what is claimed and due. */
export function counts(c: ClaimView): boolean {
  return c.status === 'OPEN' || c.status === 'PENDING' || c.status === 'SETTLED';
}

/** Whether the claim counts in the live totals for a person held or not: while held, only SETTLED ones do. */
export function countsWhile(held: boolean): (c: ClaimView) => boolean {
  return held ? (c) => c.status === 'SETTLED' : counts;
}

/** The date (yyyy-mm-dd) that decides how a claim's live figures round: its own, or for a correction the date
 *  of the claim of the same person it corrects, found among that person's claims. */
export function roundingDate(
  c: Pick<ClaimView, 'date' | 'corrects'>,
  theirs: readonly Pick<ClaimView, 'date' | 'number'>[],
): string {
  if (c.corrects === null) return c.date;
  return theirs.find((o) => o.number === c.corrects)?.date ?? c.date;
}

/** Whether a claim is overdue on the sheet's today: OPEN or PENDING and due by a day before it. */
export function isOverdue(c: Pick<ClaimView, 'dueBy' | 'status'>, today: string): boolean {
  return (c.status === 'OPEN' || c.status === 'PENDING') && c.dueBy < today;
}

/** A claim as the form submits it: a blank date takes the sheet's today. A negative amount is a correction,
 *  which names in `corrects` the number of the claim it corrects. */
export interface ClaimForm {
  amount: string;
  date: string | null;
import { HttpClient } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { Observable } from 'rxjs';

export type Grade = 'A' | 'B' | 'C';
export const GRADES: readonly Grade[] = ['A', 'B', 'C'];

/** A grade recorded for a person, in force from its from-date (yyyy-mm-dd) until the next one's; the
 *  first grade a person was given has none: it applies from the beginning of time. */
export interface GradeFrom {
  grade: Grade;
  from: string | null;
}

export interface PersonView {
  id: number;
  name: string;
  /** The grade in force on the sheet's today when the person was read. */
  grade: Grade;
  /** Every grade recorded, in the order they take effect. */
  grades: GradeFrom[];
  /** Raised on every save; an edit names the version it was made from. */
  version: number;
  /** Retired as soon as a retirement date is set, whatever the date. */
  retired: boolean;
  /** The date the person is retired from (yyyy-mm-dd); null while not retired. */
  retiredFrom: string | null;
  /** On hold: their OPEN claims count in no live total; their SETTLED ones still do. */
  held: boolean;
}

export interface PersonForm {
  name: string;
  grade: Grade;
}

/** An edit of a person: the grade is recorded from `gradeFrom` (yyyy-mm-dd; null takes the sheet's today). */
export interface PersonEdit extends PersonForm {
  gradeFrom: string | null;
}

/** The person's grade in force on `date` (yyyy-mm-dd): the one with the latest from-date on or before it. */
export function gradeOn(p: Pick<PersonView, 'grade' | 'grades'>, date: string): Grade {
  let inForce: GradeFrom | undefined;
  for (const g of p.grades) {
    if ((g.from === null || g.from <= date) && (inForce === undefined || (inForce.from ?? '') <= (g.from ?? ''))) inForce = g;
  }
  return inForce?.grade ?? p.grade;
}

// The people kept on a sheet, listed in the order they were added.
@Injectable({ providedIn: 'root' })
export class People {
  private readonly http = inject(HttpClient);
  /** Whether retired people are listed: belongs to the screen, so loading a sheet leaves it as it is. */
  readonly showRetired = signal(false);

  list(sheetId: string): Observable<PersonView[]> {
    return this.http.get<PersonView[]>(this.base(sheetId));
  }

  add(sheetId: string, person: PersonForm): Observable<PersonView> {
    return this.http.post<PersonView>(this.base(sheetId), person);
  }

  /** Save an edit made from `version` of the person; refused (412) when someone has saved them since. */
  update(sheetId: string, id: number, version: number, person: PersonEdit): Observable<PersonView> {
    return this.http.put<PersonView>(`${this.base(sheetId)}/${id}`, { ...person, version });
  }

  /** Retire the person from `from` (yyyy-mm-dd); null takes the sheet's today. */
  retire(sheetId: string, id: number, from: string | null): Observable<PersonView> {
    return this.http.post<PersonView>(`${this.base(sheetId)}/${id}/retire`, { from });
  }

  /** Put the person on hold, or take them off hold when held. */
  toggleHold(sheetId: string, id: number): Observable<PersonView> {
    return this.http.post<PersonView>(`${this.base(sheetId)}/${id}/hold`, {});
  }

  private base(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/people`;
  }
}

